    g += '<rect x="40" y="20" width="' + s.toFixed(1) + '" height="' + s.toFixed(1) + '" fill="none" stroke="var(--blue)" stroke-width="1.5" stroke-dasharray="4 3"/>';
    g += t(40 + s / 2, 25 + s / 2, "?", "f-accent f-txt");
