    g += t(160, 158, lab[2] || "", "f-txt") + t(215, 80, lab[0] || "", "f-txt", "start") + t(58, 80, lab[1] || "", "f-txt", "end");
    if (lab[3]) g += t(lab[4] === "C" ? C[0] + 6 : lab[4] === "B" ? B[0] - 40 : A[0] + 26, lab[4] === "C" ? C[1] + 30 : 132, lab[3], "f-accent f-txt", "start", 12);
