    const g = GEO().pt("A", ...A).pt("B", ...B).pt("C", ...C).pt("D", ...D).pt("E", ...E).poly(["A", "B", "C"]).seg("D", "E", { cls: "f-accent", w: 2 });
    for (const [k2, a, b] of [["AD", "A", "D"], ["DB", "D", "B"], ["AE", "A", "E"], ["EC", "E", "C"], ["DE", "D", "E"], ["BC", "B", "C"]]) if (labs[k2]) g.side(a, b, labs[k2]);
