    g.side([0, 0], [b1, 0], labs.s || "").side([0, 0], [0, b1 * r], labs.h || "").side([b1 + 1.5, 0], [b1 + 1.5 + b2, 0], labs.S || "").side([b1 + 1.5, 0], [b1 + 1.5, b2 * r], labs.H || "");
