      let g = P(pts) + '<polyline points="' + arc.map((q) => q.map((x) => x.toFixed(1)).join(",")).join(" ") + '" fill="none" class="f-accent" stroke-width="2.5"/>';
      g += t(v[0] + 36 * Math.cos(am), v[1] + 36 * Math.sin(am) + 5, lab || "?", "f-accent f-txt", "middle", 13);
