          const [cadre, unite, prod, chaque, ajoute] = R.pick([["Dans un verger, " + N0 + " pommiers donnent chacun " + Y + " kg de pommes.", "pommier", "kg", "chaque pommier donne " + k + " kg de moins", "ajouté"], ["Un apiculteur a " + N0 + " ruches ; chacune produit " + Y + " kg de miel.", "ruche", "kg", "chaque ruche produit " + k + " kg de moins (les fleurs sont partagées)", "ajoutée"], ["Dans une serre, " + N0 + " plants de tomates donnent chacun " + Y + " tomates.", "plant", "tomates", "chaque plant donne " + k + " tomates de moins", "ajouté"]]);
