// Angle associé dessiné sur le cercle trigonométrique (α dessiné à 40°).
const assocAngle = (t) => (/180° - /.test(t) ? [140, "180° − α"] : /180° \+/.test(t) ? [220, "180° + α"] : /90° - /.test(t) ? [50, "90° − α"] : /90° \+/.test(t) ? [130, "90° + α"] : [-40, "−α"]);
const cubicF = (m, s, c) => (x) => s * ((x - m) ** 3 - 3 * (x - m)) + c; // maximum local en m − 1, minimum local en m + 1
const degT = (v) => v + "°";
