V34("fracmul",
  () => { const [a, b] = irr(2, 5), [c, d] = irr(2, 5), [e, f] = irr(2, 7); const v = (a / b + c / d) * (e / f); return QV("Calcule et simplifie : " + M("\\left(\\frac{" + a + "}{" + b + "} + \\frac{" + c + "}{" + d + "}\\right) \\cdot \\frac{" + e + "}{" + f + "}"), v, "Parenthèse : " + M(frac(a * d + c * b, b * d)) + ", puis " + M(frac((a * d + c * b) * e, b * d * f)) + "."); },
  () => { let a, b, n, c, d, v; do { [a, b] = irr(2, 7); n = R.int(1, 3); [c, d] = irr(2, 5); v = (a / b) * (n - c / d); } while ([a, b, c, d, n].some((x) => Math.abs(x - v) < 1e-9)); return QV("Calcule et simplifie : " + M("\\frac{" + a + "}{" + b + "} \\cdot \\left(" + n + " - \\frac{" + c + "}{" + d + "}\\right)"), v, "Parenthèse : " + M(frac(n * d - c, d)) + ", puis " + M(frac(a * (n * d - c), b * d)) + "."); },
);
V("fracops", 1,
  () => { const [a, b] = irr(2, 9), n = R.int(1, 3); return QV("Calcule et simplifie : " + M("\\frac{" + a + "}{" + b + "} - " + n), a / b - n, M("\\frac{" + a + "}{" + b + "} - \\frac{" + n * b + "}{" + b + "} = " + frac(a - n * b, b)) + "."); },
  () => { let a, b, c, d; do { [a, b] = irr(2, 6); [c, d] = irr(2, 6); } while (b === d || c / d >= a / b); return QV("Calcule et simplifie : " + M("-\\frac{" + a + "}{" + b + "} + \\frac{" + c + "}{" + d + "}"), c / d - a / b, "Dénominateur commun : " + M(frac(c * b - a * d, b * d)) + " (négatif)."); },
);
V34("fracops",
  () => { let a, b, c, d, n, v; do { [a, b] = irr(2, 6); [c, d] = irr(2, 6); n = R.int(1, 3); v = (a / b) / (c / d) - n; } while ((a === c && b === d) || Math.abs(v) < 1e-9 || Math.abs(Math.abs(v) - 1) < 1e-9); return QV("Calcule et simplifie : " + M("\\frac{" + a + "}{" + b + "} : \\frac{" + c + "}{" + d + "} - " + n), v, "D'abord la division : " + M(frac(a * d, b * c)) + ", puis on retire " + n + " : " + M(frac(a * d - n * b * c, b * c)) + "."); },
  () => { const [a, b] = irr(2, 5), [c, d] = irr(2, 9); const v = (a / b) ** 2 - c / d; if (Math.abs(v) < 1e-9) return VAR.fracops[3][0](); return QV("Calcule et simplifie : " + M("\\left(\\frac{" + a + "}{" + b + "}\\right)^2 - \\frac{" + c + "}{" + d + "}"), v, "La puissance d'abord : " + M("\\frac{" + a * a + "}{" + b * b + "}") + ", puis " + M(frac(a * a * d - c * b * b, b * b * d)) + "."); },
);
V("pct", 1,
  () => { const n = R.pick([400, 500, 600, 650, 750, 800]), p = R.pick([12, 15, 18, 24, 35]); return Object.assign(QV("Un collège compte " + n + " élèves ; " + p + " % d'entre eux viennent en bus. Combien d'élèves viennent en bus ?", (n * p) / 100, M("\\frac{" + p + "}{100} \\cdot " + n + " = " + (n * p) / 100) + " élèves."), { guide: [GS("Combien font " + M("1\\,\\%") + " de " + M(n) + " ? (on divise par 100)", n / 100, M(n + " \\div 100 = " + dec(n / 100)) + "."), GS("Et " + M(p + "\\,\\%") + " ?", (n * p) / 100, M(p + " \\cdot " + dec(n / 100) + " = " + (n * p) / 100) + " élèves.")], traps: [TRAP(n - (n * p) / 100, "Ça, ce sont les élèves qui ne viennent pas en bus."), TRAP(n / p, "p % de n, c'est p/100 · n, pas n ÷ p.")] }); },
  () => { const p = R.pick([2.5, 3.5, 3.2, 1.5]), m = R.pick([1000, 500, 250]); return Object.assign(QV("Un lait contient " + dT(p) + " % de matières grasses. Combien de grammes de matières grasses y a-t-il dans " + m + " g de lait ?", r6((p * m) / 100), M("\\frac{" + dec(p) + "}{100} \\cdot " + m + " = " + dec(r6((p * m) / 100))) + " g."), { guide: [GS("Combien font " + M("1\\,\\%") + " de " + M(m + "\\text{ g}") + " ?", m / 100, M(m + " \\div 100 = " + dec(m / 100)) + " g."), GS("Et " + M(dec(p) + "\\,\\%") + " ?", r6((p * m) / 100), M(dec(p) + " \\cdot " + dec(m / 100) + " = " + dec(r6((p * m) / 100))) + " g.")], traps: [TRAP(p * m, "N'oublie pas de diviser par 100."), TRAP(m / p, "p % de m, c'est p/100 · m.")] }); },
);
V34("pct",
  () => { const p = R.pick([10, 20, 25, 30, 40]), x = R.int(4, 20) * 10; const y = r6(x * (1 - p / 100)); return Object.assign(QV("Après une baisse de " + p + " %, un prix vaut " + M(dec(y)) + " CHF. Quel était le prix de départ (en CHF) ?", x, M(dec(y) + " \\div " + dec(1 - p / 100) + " = " + x) + " CHF (on divise, on n'ajoute pas " + p + " %)."), { guide: [GS("Une baisse de " + M(p + "\\,\\%") + " multiplie le prix de départ par quel nombre ?", 1 - p / 100, M("1 - \\frac{" + p + "}{100} = " + dec(1 - p / 100)) + "."), GS("Pour revenir en arrière, on divise : " + M(dec(y) + " \\div " + dec(1 - p / 100)) + " = ?", x, M(x) + " CHF.")], traps: [TRAP(r6(y * (1 + p / 100)), "On n'ajoute pas " + p + " % au nouveau prix : la baisse était calculée sur le prix de départ."), TRAP(r6(y * (1 - p / 100)), "On divise par " + dec(1 - p / 100) + ", on ne multiplie pas.")] }); },
  () => { const p = R.pick([20, 25, 50]), x = R.int(4, 16) * 20; return Object.assign(QV("En un an, le nombre de membres d'un club a augmenté de " + p + " % ; il y en a maintenant " + r6(x * (1 + p / 100)) + ". Combien y en avait-il avant ?", x, M(r6(x * (1 + p / 100)) + " \\div " + dec(1 + p / 100) + " = " + x) + "."), { guide: [GS("Une hausse de " + M(p + "\\,\\%") + " multiplie l'effectif de départ par quel nombre ?", 1 + p / 100, M("1 + \\frac{" + p + "}{100} = " + dec(1 + p / 100)) + "."), GS("On divise : " + M(r6(x * (1 + p / 100)) + " \\div " + dec(1 + p / 100)) + " = ?", x, M(x) + " membres.")], traps: [TRAP(r6(x * (1 + p / 100) * (1 - p / 100)), "On ne retire pas " + p + " % du nouvel effectif : la hausse portait sur l'ancien."), TRAP(r6(x * (1 + p / 100) - p), "Ce sont des pourcents, pas des membres.")] }); },
);
