V("polyreg", 1,
  () => { const [n, nom] = R.pick([[6, "hexagone"], [5, "pentagone"], [10, "décagone"], [12, "dodécagone"], [8, "octogone"]]); return QV("Quelle est la mesure de l'angle au centre d'un " + nom + " régulier (en degrés) ?", 360 / n, "Un " + nom + " a " + n + " côtés : " + M("\\frac{360°}{" + n + "} = " + 360 / n + "°") + ".", { traps: [TRAP(180 / n, "Le tour complet autour du centre mesure 360°."), TRAP(180 - 360 / n, "C'est l'angle intérieur ; l'angle au centre vaut 360° : " + n + ".")] }); },
  () => { const n = R.pick([5, 6, 8, 9, 10, 12]); return QV("Une roue a " + n + " rayons régulièrement espacés. Quel angle forment deux rayons voisins (en degrés) ?", 360 / n, M("360° : " + n + " = " + 360 / n + "°") + ".", { traps: [TRAP(180 / n, "Le tour complet mesure 360°."), TRAP(360 / (n - 1), "Il y a " + n + " angles entre " + n + " rayons (on revient au premier).")] }); },
);
V("polyreg", 2,
  () => { const n = R.int(5, 12); return QV("Quelle est la somme des angles intérieurs d'un polygone à " + n + " côtés (en degrés) ?", (n - 2) * 180, M("(" + n + " - 2) \\cdot 180° = " + (n - 2) * 180 + "°") + ".", { traps: [TRAP(n * 180, "Un polygone à " + n + " côtés se découpe en " + (n - 2) + " triangles, pas " + n + "."), TRAP(360, "360° est la somme pour un quadrilatère seulement.")] }); },
  () => { const [n, nom] = R.pick([[5, "pentagone"], [6, "hexagone"], [8, "octogone"], [10, "décagone"]]); return QV("Quelle est la mesure d'un angle intérieur d'un " + nom + " régulier, c'est-à-dire l'angle entre deux côtés voisins (marqué sur la figure), en degrés ?", 180 - 360 / n, "Angle au centre " + M("\\frac{360°}{" + n + "} = " + 360 / n + "°") + " ; angle intérieur " + M("180° - " + 360 / n + "° = " + (180 - 360 / n) + "°") + ".", { traps: [TRAP(360 / n, "C'est l'angle au centre ; l'angle intérieur vaut 180° − " + 360 / n + "°."), TRAP(180 / n, "Angle intérieur = 180° − angle au centre.")], fig: FIG.regPoly(n, "?", true) }); },
);
V34("polyreg",
  () => { const n = R.pick([5, 6, 8, 9, 10, 12, 15, 18]); return QV("L'angle au centre d'un polygone régulier mesure " + 360 / n + "°. Combien le polygone a-t-il de côtés ?", n, M("\\frac{360}{" + 360 / n + "} = " + n) + ".", { traps: [TRAP(180 / (360 / n), "Le tour complet mesure 360°, pas 180°."), TRAP(n + 2, "Nombre de côtés = 360° : angle au centre.")] }); },
  () => { const n = R.int(6, 12); return QV("La somme des angles intérieurs d'un polygone vaut " + mille((n - 2) * 180) + "°. Combien a-t-il de côtés ?", n, M("(n - 2) \\cdot 180 = " + (n - 2) * 180 + " \\iff n - 2 = " + (n - 2) + " \\iff n = " + n) + ".", { traps: [TRAP(n - 2, "C'est le nombre de triangles ; le polygone a 2 côtés de plus."), TRAP(((n - 2) * 180) / 180, "(n − 2) · 180 = " + (n - 2) * 180 + " donne n − 2 = " + (n - 2) + ", puis n.")] }); },
);
