  // ===================== morceaux : fonctions définies par morceaux (20.11) =====================
  const PCW = (p1, c, p2) => M("f(x) = \\begin{cases} " + p1 + " & \\text{si } x < " + c + " \\\\ " + p2 + " & \\text{si } x \\ge " + c + " \\end{cases}");
