  const linD = (m, h) => (m === 1 ? "" : m === -1 ? "-" : N(m)) + "x" + (h ? (h < 0 ? " - " + N(-h) : " + " + N(h)) : ""); // coefficients décimaux (contextes)
  const C = (v) => (Number.isInteger(r6(v)) ? N(v) : r6(v).toFixed(2).replace(".", "{,}")); // CHF
