      do { e.length = 0; [0.35, 0.2, 0.15, 0.1].forEach((p) => e.push(Math.max(2, Math.round(Nt * p * (0.7 + 0.6 * R.rand()))))); e.push(Nt - e.reduce((s, x) => s + x, 0)); } while (e[4] < 3);
