        bet: { q: "À quelle hauteur au-dessus du sol se trouve-t-elle ?", choices: ["Moins d'un millimètre", "Environ un centimètre", "Assez haut pour qu'un chat " + (L === 1 ? "maigre " : "") + "passe dessous"], good: 2 },
