      const m = pk([50, 100, 200]), [w1, w2] = pk([[99, 98], [99, 97], [98, 96], [99, 96]]), dry = (m * (100 - w1)) / 100, F = dry / ((100 - w2) / 100), [food, fem] = pk([["pommes de terre", 1], ["concombres", 0], ["pastèques", 1]]), E = fem ? "elles" : "ils", fa = fem ? "faites" : "faits";
