          if (d && o.nudge) { o.nudge(st, k, d[0], d[1], step); e.preventDefault(); after(k); }
          else if ((e.key === "Enter" || e.key === " ") && o.tap) { o.tap(st, k, step); e.preventDefault(); after(k); }
